csharp\nusing TMPro;\nusing UnityEngine;\nusing UnityEngine.UI;\nusing AirHockey.Networking.Lobby;\nusing AirHockey.Networking;\n\nnamespace AirHockey.UI\n{\n public class LobbyUI : MonoBehaviour\n {\n [SerializeField] private TMP_InputField eloInput;\n [SerializeField] private Button quickPlayBtn;\n [SerializeField] private TextMeshProUGUI statusTxt;\n [SerializeField] private NetworkGameManager netMgr;\n\n private void Awake() => quickPlayBtn.onClick.AddListener(OnQuickPlay);\n\n private async void OnQuickPlay()\n {\n statusTxt.text = \"Recherche de partie…\";\n int elo = int.TryParse(eloInput.text, out var e) ? e : 1000;\n string room = await MatchmakingService.FindMatchAsync(elo);\n\n statusTxt.text = \"Connexion au room…\";\n await netMgr.StartOrJoinAsync(room);\n }\n }\n}\n